dtsPropsFor.MasterTable:
/** Rows to render. Any object shape; columns pull fields off it. */
  rows: Row[];
  /** Column definitions, left to right. */
  columns: {
    key: string;
    label: string;
    render: (row: Row) => React.ReactNode;
    /** Plain text for search and the phone card view. */
    text?: (row: Row) => string;
    width?: number;
    /** Hidden in the phone card view. */
    minor?: boolean;
  }[];
  /** Stable id per row. */
  idOf: (row: Row) => string;
  /** Status pill, never scrolled out of view. */
  statusOf?: (row: Row) => { label: string; color: string; bg: string };
  /** Search placeholder, phrased for this data. */
  searchHint: string;
  /** Primary create action. Omit for read-only tables. */
  addLabel?: string;
  onAdd?: () => void;
  onEdit?: (row: Row) => void;
  onDelete?: (row: Row) => void;
  onExport?: () => void;
  /** Shown when the data set is empty, as opposed to filtered empty. */
  emptyTitle: string;
  emptyBody: string;
  pageSize?: number;

dtsPropsFor.MonthCalendar:
sessions: AdminSession[];
  selected: string | null;
  onSelect: (k: string | null) => void;
  year?: number;
  month?: number;
  /** yyyy-mm-dd highlighted as today. */
  today?: string;

dtsPropsFor.DayList:
dayKey: string | null;
  sessions: AdminSession[];
  onOpenRequest?: (s: AdminSession) => void;
  emptyHint?: string;

dtsPropsFor.RequestDetail:
request: BookletRequest | null;
  onClose: () => void;
  onApprove?: (id: string, note: string) => void;
  onReject?: (id: string, reason: string) => void;
  /** Saves a corrected printer or print format back onto the request. */
  onUpdate?: (id: string, patch: { printer?: string; format?: PrintFormat }) => void;
  readOnly?: boolean;

dtsPropsFor.ScheduleClassModal:
onClose: () => void;
  onCreate: (s: Omit<AdminSession, "id">) => void;
  /** yyyy-mm-dd the form opens on. */
  defaultDay: string | null;

dtsPropsFor.AssessmentTable:
outline: Outline;
  onUpdate: (assessmentId: string, patch: Partial<Pick<Assessment, "weight" | "score" | "done">>) => void;
  compact?: boolean;

dtsPropsFor.PdfPreviewModal:
open: boolean;
  onClose: () => void;
  fileName: string;
  meta?: string;
  /** "doc" is a view+annotate preview, "video" watch-only, "link" an in-portal URL preview. */
  kind?: "doc" | "video" | "link";
  /** Shown in the mock browser bar when kind is "link". */
  url?: string;
  /** False gives a plain read-only viewer with no annotation toolbar. */
  annotate?: boolean;
  /** True length of the document, shown even though only previewLimit pages render. */
  pages?: number;
  previewLimit?: number;
  onSaveAnnotations?: (dataUrl: string) => void;
  saveLabel?: string;

dtsPropsFor.BookletStatsPanel:
requests: BookletRequest[];
  courseId?: TutorCourseId;
  title?: string;
  subtitle?: string;
  height?: number;

dtsPropsFor.ElliotMark:
/** Width in px. Height is 0.593x this. */
